use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl TyKind { pub fn is_implicit_self (& self) -> bool { matches ! (self , TyKind :: ImplicitSelf) } pub fn is_unit (& self) -> bool { matches ! (self , TyKind :: Tup (tys) if tys . is_empty ()) } pub fn is_simple_path (& self) -> Option < Symbol > { if let TyKind :: Path (None , Path { segments , .. }) = & self && let [segment] = & segments [..] && segment . args . is_none () { Some (segment . ident . name) } else { None } } # [doc = " Returns `true` if this type is considered a scalar primitive (e.g.,"] # [doc = " `i32`, `u8`, `bool`, etc)."] # [doc = ""] # [doc = " This check is based on **symbol equality** and does **not** remove any"] # [doc = " path prefixes or references. If a type alias or shadowing is present"] # [doc = " (e.g., `type i32 = CustomType;`), this method will still return `true`"] # [doc = " for `i32`, even though it may not refer to the primitive type."] pub fn maybe_scalar (& self) -> bool { let Some (ty_sym) = self . is_simple_path () else { return self . is_unit () ; } ; matches ! (ty_sym , sym :: i8 | sym :: i16 | sym :: i32 | sym :: i64 | sym :: i128 | sym :: u8 | sym :: u16 | sym :: u32 | sym :: u64 | sym :: u128 | sym :: f16 | sym :: f32 | sym :: f64 | sym :: f128 | sym :: char | sym :: bool) } }
}